const cfg=window.STORE_CONFIG||{}; const nets=["MTN","Airtel","Glo","9mobile"]; let selected={data:null,airtime:null}; let catalogue=null; let sb=null,user=null;
const $=id=>document.getElementById(id); const money=n=>`₦${Number(n||0).toLocaleString("en-NG",{minimumFractionDigits:2,maximumFractionDigits:2})}`;
function closeAlert(){$("alert").style.display="none";localStorage.setItem("ac-alert","seen")} if(localStorage.getItem("ac-alert")==="seen")$("alert").style.display="none";
function toggleMenu(){$("menu").classList.toggle("open");$("shade").classList.toggle("open")}
function go(id){document.querySelectorAll(".page").forEach(x=>x.classList.remove("active"));$(id).classList.add("active");$("menu").classList.remove("open");$("shade").classList.remove("open");scrollTo(0,0);if(id==="transactions")loadTransactions();if(id==="wallet")loadFunding()}
function authMode(mode){const signup=mode==="signup";$("nameWrap").classList.toggle("hidden",!signup);$("authPhoneWrap").classList.toggle("hidden",!signup);$("loginTab").classList.toggle("on",!signup);$("signupTab").classList.toggle("on",signup);$("authSubmit").textContent=signup?"Create account":"Sign in";$("authSubmit").dataset.mode=mode;$("authTitle").textContent=signup?"Create your account":"Welcome back";$("authLead").textContent=signup?"Create one account for your wallet and services.":"Sign in to continue to your account.";$("confirmationBox").classList.add("hidden");$("authMessage").textContent=""}
async function submitAuth(){if(!sb)return authError("Add your Supabase URL and anon key in config.js first.");const email=$("authEmail").value.trim(),password=$("authPassword").value,mode=$("authSubmit").dataset.mode||"login";let res;if(mode==="signup")res=await sb.auth.signUp({email,password,options:{data:{full_name:$("authName").value.trim(),phone:$("authPhone").value.trim()}}});else res=await sb.auth.signInWithPassword({email,password});if(res.error)return authError(res.error.message);if(mode==="signup"&&!res.data.session){$("confirmationBox").classList.remove("hidden");$("authMessage").textContent="";return;}user=res.data.user;await enterApp()}
function authError(m){$("authMessage").textContent=m}
async function signOut(){if(sb)await sb.auth.signOut();location.reload()}
async function enterApp(){$("authGate").classList.add("hidden");if(!user)return;$("profileEmail").textContent=user.email||"—";$("avatarBtn").textContent=(user.user_metadata?.full_name||user.email||"A")[0].toUpperCase();await Promise.all([loadProfile(),loadWallet(),loadTransactions(),loadFunding(),loadCatalogue()])}
async function loadProfile(){const {data}=await sb.from("profiles").select("full_name,username,phone").eq("id",user.id).maybeSingle();if(!data)return;$("profileName").textContent=data.full_name||"—";$("profileUsername").textContent=data.username||"Not set";$("profilePhone").textContent=data.phone||"Not set";if($("welcomeName"))$("welcomeName").textContent=(data.full_name?`Hi, ${data.full_name.split(" ")[0]} 👋`:"Your digital services, in one place.");if($("profileAvatar"))$("profileAvatar").textContent=(data.full_name||user.email||"A")[0].toUpperCase()}
async function loadWallet(){const {data}=await sb.from("wallets").select("balance").eq("user_id",user.id).maybeSingle();const value=money(data?.balance||0);$("walletBalance").textContent=value;document.querySelectorAll(".summary p:last-child b").forEach(x=>x.textContent=value)}
async function loadTransactions(){if(!sb||!user)return;const {data}=await sb.from("transactions").select("*").eq("user_id",user.id).order("created_at",{ascending:false}).limit(30);const box=$("transactionList");const html=data?.length?data.map(t=>`<div class="listitem"><div><b>${esc(t.description||t.type)}</b><small>${new Date(t.created_at).toLocaleString()}</small></div><div><b>${money(t.amount)}</b><small class="status ${esc(t.status)}">${esc(t.status)}</small></div></div>`).join(""):'<span class="muted">No transactions yet.</span>';if(box)box.innerHTML=html;const dash=$("dashboardTransactions");if(dash){dash.className=data?.length?"activity list":"activity empty-state";dash.innerHTML=data?.length?data.slice(0,4).map(t=>`<div class="listitem"><div><b>${esc(t.description||t.type)}</b><small>${new Date(t.created_at).toLocaleDateString()}</small></div><div><b>${money(t.amount)}</b><small class="status ${esc(t.status)}">${esc(t.status)}</small></div></div>`).join(""):'<b>No transactions yet</b><span>Your purchases and wallet activity will appear here.</span>'}}
async function loadFunding(){if(!sb||!user)return;const {data}=await sb.from("funding_requests").select("*").eq("user_id",user.id).order("created_at",{ascending:false}).limit(10);const box=$("fundingList");if(!box)return;box.innerHTML=data?.length?data.map(f=>`<div class="listitem"><div><b>${money(f.amount)}</b><small>${new Date(f.created_at).toLocaleString()}</small></div><small class="status ${esc(f.status)}">${esc(f.status)}</small></div>`).join(""):'<span class="muted">No funding requests yet.</span>'}
async function submitFunding(){const amount=Number($("fundAmount").value),ref=$("fundReference").value.trim();if(!amount||amount<=0)return alert("Enter a valid funding amount.");if(!sb||!user)return;const {error}=await sb.from("funding_requests").insert({user_id:user.id,amount,payment_reference:ref||null});if(error)return alert(error.message);$("fundAmount").value="";$("fundReference").value="";await loadFunding();alert("Funding request submitted for review.")}
async function proxy(action,payload={}){
 const {data:{session}}=await sb.auth.getSession();
 if(!session)throw new Error("Please sign in again.");
 const r=await fetch("/api/backend",{
   method:"POST",
   headers:{
     Authorization:`Bearer ${session.access_token}`,
     "Content-Type":"application/json"
   },
   body:JSON.stringify({action,payload})
 });
 const data=await r.json();
 if(!r.ok)throw new Error(data.error||data.message||"Request failed");
 return data
}
async function loadCatalogue(){const box=document.querySelector(".apiwait");if(!box||!sb)return;try{catalogue=await proxy("catalogue");const plans=catalogue?.data?.plans||catalogue?.plans||[];const networks=catalogue?.data?.networks||catalogue?.airtime?.networks||[];if(!plans.length){box.textContent="No data plans are currently available.";return}box.className="plans-live";box.innerHTML=plans.map((p,i)=>`<button class="plan-live" data-i="${i}"><b>${esc(p.name||"Data plan")}</b><small>${money(Number(p.price?.amount_minor||0)/Math.pow(10,Number(p.price?.minor_unit||0)))}</small></button>`).join("");box.querySelectorAll("button").forEach((b,i)=>b.onclick=()=>{selected.data={plan:plans[i],network:networks.find(n=>n.id===plans[i].network_id)};box.querySelectorAll("button").forEach(x=>x.classList.remove("selected"));b.classList.add("selected");$("dataCheckoutText").textContent=`${plans[i].name} · ${money(Number(plans[i].price.amount_minor)/Math.pow(10,Number(plans[i].price.minor_unit||0)))}`;$("dataBuyBtn").disabled=false})}catch(e){box.textContent=`Live plans unavailable: ${e.message}`}}
function upstreamNetwork(name){const all=catalogue?.airtime?.networks||catalogue?.data?.networks||[];return all.find(n=>String(n.name).toLowerCase()===String(name).toLowerCase()||String(n.code).toLowerCase()===String(name).toLowerCase())}
async function dataOrder(){const phone=$("dataPhone").value.trim(),x=selected.data;if(!x?.plan||!phone)return alert("Select a data plan and enter the phone number.");const amount=Number(x.plan.price.amount_minor)/Math.pow(10,Number(x.plan.price.minor_unit||0));try{const key=`ac_${user.id}_${Date.now()}_${crypto.randomUUID()}`;const r=await proxy("purchase",{service_type:"data",network_id:x.plan.network_id,network_name:x.network?.name||"",data_plan_id:x.plan.id,phone_number:phone,customer_amount:amount,idempotency_key:key});alert(r.message||"Data order submitted.");await Promise.all([loadWallet(),loadTransactions()]);go("transactions")}catch(e){alert(e.message)}}
function updateAir(){$("sumPhone").textContent=$("airPhone").value||"—";$("sumAmount").textContent=$("airAmount").value?money($("airAmount").value):"—"}$("airPhone").oninput=updateAir;$("airAmount").oninput=updateAir;
async function airtimeOrder(){if(!selected.airtime||!$("airPhone").value||!Number($("airAmount").value))return alert("Select a network, enter the phone number and amount.");const network=upstreamNetwork(selected.airtime);if(!network)return alert("This network is not currently available.");try{const amount=Number($("airAmount").value),key=`ac_${user.id}_${Date.now()}_${crypto.randomUUID()}`;const r=await proxy("purchase",{service_type:"airtime",network_id:network.id,network_name:network.name,phone_number:$("airPhone").value.trim(),amount,customer_amount:amount,idempotency_key:key});alert(r.message||"Airtime order submitted.");await Promise.all([loadWallet(),loadTransactions()]);go("transactions")}catch(e){alert(e.message)}}
function esc(v){return String(v??"").replace(/[&<>\"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
document.querySelectorAll(".networks").forEach(box=>{const group=box.dataset.group;nets.forEach(n=>{const b=document.createElement("button");b.className="net";b.innerHTML=`<i>${n==="9mobile"?"9M":n.slice(0,3).toUpperCase()}</i>${n}`;b.onclick=()=>{box.querySelectorAll(".net").forEach(x=>x.classList.remove("selected"));b.classList.add("selected");selected[group]=n;if(group==="airtime")$("sumNet").textContent=n};box.appendChild(b)})});
[50,100,200,300,500,1000].forEach(n=>{const b=document.createElement("button");b.textContent=money(n).replace(".00","");b.onclick=()=>{$("airAmount").value=n;updateAir()};document.querySelector(".amounts").appendChild(b)});[500,1000,2000,5000,10000].forEach(n=>{const b=document.createElement("button");b.textContent=money(n).replace(".00","");b.onclick=()=>$("fundAmount").value=n;document.querySelector(".fundamounts").appendChild(b)});
const bank=cfg.bank||{};if(bank.bankName&&bank.accountNumber)$("bankDetails").innerHTML=`<b>${esc(bank.bankName)}</b><br>${esc(bank.accountNumber)}<br>${esc(bank.accountName||"")}`;
(async()=>{if(!cfg.supabaseUrl||!cfg.supabaseAnonKey){authError("Setup required: add Supabase URL and anon key to config.js.");return}sb=window.supabase.createClient(cfg.supabaseUrl,cfg.supabaseAnonKey);const {data:{session}}=await sb.auth.getSession();user=session?.user||null;sb.auth.onAuthStateChange((_e,s)=>{user=s?.user||null});if(user)await enterApp()})();

function copyAccount(){navigator.clipboard?.writeText((cfg.bank||{}).accountNumber||"2548335435").then(()=>alert("Account number copied."));}
